// Collects records/step-*/meta.json + prompt files into data/steps.js for the viewer.
// The records directory is the source of truth; data/steps.js is generated (do not edit by hand).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const recDir = path.join(root, 'records');
const dirs = fs.readdirSync(recDir).filter((d) => /^step-\d+/.test(d)).sort();

const steps = dirs.map((d) => {
  const meta = JSON.parse(fs.readFileSync(path.join(recDir, d, 'meta.json'), 'utf8'));
  const prompts = (meta.prompts || []).map((p) => ({
    label: p.label,
    file: `records/${d}/${p.file}`,
    text: fs.readFileSync(path.join(recDir, d, p.file), 'utf8').replace(/\s+$/, ''),
  }));
  const shots = {};
  for (const v of ['mobile', 'tablet', 'desktop']) {
    const f = `screenshots/${d}/${v}.jpg`;
    if (fs.existsSync(path.join(root, f))) shots[v] = f;
  }
  const site = `steps/${d}/index.html`;
  if (!fs.existsSync(path.join(root, site))) throw new Error(`missing snapshot: ${site}`);
  return { ...meta, id: d, site, prompts, screenshots: shots };
});

const out = `// GENERATED by tools/build-data.mjs from records/ — do not edit.\nwindow.DESLOP_STEPS = ${JSON.stringify(steps, null, 2)};\n`;
fs.mkdirSync(path.join(root, 'data'), { recursive: true });
fs.writeFileSync(path.join(root, 'data', 'steps.js'), out);
console.log(`data/steps.js: ${steps.length} steps`);
